// Identidad exacta del servicio. Las filas vigentes se leen de Google Sheets.
function spaNorm(v) {
  return String(v ?? '').normalize('NFD').replace(/[\u0300-\u036f]/g, '')
    .toLowerCase().replace(/buddha|budhas|budas|buda\b/g, 'budha')
    .replace(/fulldayspa/g, 'full day spa').replace(/3\s*p(?:x|ax)\b/g, 'tribu')
    .replace(/[^a-z0-9]+/g, ' ').replace(/\s+/g, ' ').trim();
}
function spaFamily(v, n) {
  let t = spaNorm(v).replace(/^(masaje|jacuzzi) /, '');
  t = t.replace(/^sauna elephant glow/, 'elephant glow').replace(/^premium budha/, 'budha');
  const m = t.match(/^(premium(?: day(?: spa)?)?(?: facial)?|full(?: day(?: spa)?)?|budha(?: 70)?|temazcal bliss|elephant glow)(?: (individual|pareja|tribu))?$/);
  if (!m) return null;
  const root = m[1].startsWith('premium') ? (m[1].includes('facial') ? 'premium_day_spa_facial' : 'premium_day_spa')
    : m[1].startsWith('full') ? 'full_day_spa' : m[1].startsWith('budha') ? 'budha_70' : m[1].replace(/ /g, '_');
  const mod = m[2] || (n === 1 ? 'individual' : n === 2 ? 'pareja' : n >= 3 ? 'tribu' : '');
  return {root, mod, canonical: root + (mod ? '_' + mod : '')};
}
function spaCanonical(v, n) {
  const f = spaFamily(v, n);
  return f ? f.canonical : spaNorm(v).replace(/ /g, '_') || null;
}
function spaId(r) { const v=r.ID ?? r[' '] ?? r.id; return /^\d+(?:\.0+)?$/.test(String(v??'').trim()) ? String(Number(v)) : ''; }
function spaYes(v) { return ['si','true','1','yes'].includes(spaNorm(v)); }
function spaActive(r) { return spaYes(r.Activo) && !spaNorm(r['Categoría']).includes('disabled'); }
const SPA_SAUNA_IDS = {individual:['3570984','3570987'],pareja:['3570985','3570988'],tribu:['3570986','3570989']};
const Personal=(()=>{const HEADERS=['Clave','Sucursal_ID','Sucursal','Empleado_ID','Nombre','Cargo','Estado_API','Presente_API','Servicios_ID','Modo','Ultima_consulta_OK','Ultima_vez_visto','Tipo','Observaciones'];
const BRANCHES={'24077':'Valle','24079':'Polanco','24080':'Juárez','24082':'Lomas','24221':'Roma'};
function norm(v){return String(v??'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').trim().toLowerCase();}
function validId(v){return /^[1-9]\d*$/.test(String(v??''));}
function body(r){let b=r?.body??r?.data??r;if(typeof b==='string'){try{b=JSON.parse(b);}catch{throw Error('RESPUESTA_NO_JSON');}}return b;}
function records(values){
 if(!Array.isArray(values)||!values.length)return [];
 if(HEADERS.some((h,i)=>values[0][i]!==h))throw Error('ENCABEZADOS_PERSONAL_NO_COINCIDEN');
 const out=values.slice(1).filter(r=>r.some(v=>String(v??'').trim())).map(r=>Object.fromEntries(HEADERS.map((h,i)=>[h,r[i]??''])));
 const seen=new Set();for(const r of out){if(!BRANCHES[String(r.Sucursal_ID)]||!validId(r.Empleado_ID)||r.Clave!==r.Sucursal_ID+':'+r.Empleado_ID||seen.has(r.Clave))throw Error('CLAVE_PERSONAL_INVALIDA_O_DUPLICADA');seen.add(r.Clave);if(!['AUTO','SI','NO'].includes(String(r.Modo).toUpperCase()))throw Error('MODO_PERSONAL_INVALIDO');}
 return out;
}
function kind(u){const name=norm(u.full_name);if(/\b(jacuzzi|sauna|temazcal|cabina|camilla|room)\b/.test(name))return 'RECURSO';if(/^inside\b/.test(name))return 'CUENTA_INTERNA';if(norm(u.job_title)==='employee'&&Number(u.admin)===0)return 'CANDIDATA_TERAPEUTA';return 'REVISAR_ROL';}
function usable(r){
 const mode=String(r.Modo).toUpperCase(),status=norm(r.Estado_API);
 return String(r.Presente_API)==='SI'&&['','pending','active','enabled'].includes(status)&&!['RECURSO','CUENTA_INTERNA'].includes(r.Tipo)&&mode!=='NO'&&(mode==='SI'||(mode==='AUTO'&&r.Tipo==='CANDIDATA_TERAPEUTA'));
}
function sync(responses,oldValues,stamp){
 const old=records(oldValues),fresh=new Map(),seenBranches=new Set();
 for(const entry of responses){
  const branch=String(entry.sucursal_id);if(!BRANCHES[branch]||seenBranches.has(branch))throw Error('SUCURSAL_INVALIDA_O_DUPLICADA');seenBranches.add(branch);
  const r=entry.respuesta;
  if(entry.codigo_http!==200||entry.consulta_http_exitosa!==true||entry.fallo_consulta||r?.success!==true||!Array.isArray(r.users)||!Number.isInteger(r.total)||r.total<=0||r.total!==r.users.length)throw Error('CONSULTA_PERSONAL_INCOMPLETA_'+branch);
  if(r.has_more===true||r.next_page||r.next||r.pagination?.has_more===true||Number(r.pagination?.total_pages||1)>1)throw Error('PERSONAL_PAGINADO_NO_COMPLETO_'+branch);
  for(const u of r.users){
   if(!validId(u.id)||!String(u.full_name??'').trim()||typeof u.job_title!=='string'||![0,1].includes(Number(u.admin))||!Array.isArray(u.assigned_locations)||!u.assigned_locations.every(validId)||!Array.isArray(u.assigned_services)||!u.assigned_services.every(validId))throw Error('USUARIO_PERSONAL_INVALIDO_'+branch);
   if(!u.assigned_locations.map(String).includes(branch))throw Error('USUARIO_DE_OTRA_SUCURSAL_'+branch);
   const key=branch+':'+u.id;if(fresh.has(key))throw Error('USUARIO_DUPLICADO_'+key);
   const prev=old.find(x=>x.Clave===key);
   fresh.set(key,{Clave:key,Sucursal_ID:branch,Sucursal:BRANCHES[branch],Empleado_ID:String(u.id),Nombre:u.full_name.trim(),Cargo:u.job_title,Estado_API:String(u.status??''),Presente_API:'SI',Servicios_ID:JSON.stringify([...new Set(u.assigned_services.map(String))]),Modo:prev?.Modo||'AUTO',Ultima_consulta_OK:stamp,Ultima_vez_visto:stamp,Tipo:kind(u),Observaciones:prev?.Observaciones||''});
  }
 }
 if(seenBranches.size!==5)throw Error('FALTAN_SUCURSALES');
 // Una ausencia solo se aplica después de validar las cinco consultas completas.
 for(const prev of old)if(!fresh.has(prev.Clave))fresh.set(prev.Clave,{...prev,Presente_API:'NO',Ultima_consulta_OK:stamp});
 const rows=[...fresh.values()].sort((a,b)=>a.Sucursal_ID.localeCompare(b.Sucursal_ID)||a.Nombre.localeCompare(b.Nombre));
 if(rows.length>=999)throw Error('CAPACIDAD_HOJA_PERSONAL_EXCEDIDA');
 return [HEADERS,...rows.map(r=>HEADERS.map(h=>String(r[h]??'')))];
}
function catalog(values,now){
 const rows=records(values);if(!rows.length)throw Error('PERSONAL_NO_SINCRONIZADO');
 for(const branch of Object.keys(BRANCHES)){
  const rr=rows.filter(r=>r.Sucursal_ID===branch);if(!rr.length)throw Error('PERSONAL_SUCURSAL_SIN_DATOS_'+branch);
  for(const r of rr){const elapsed=now-Date.parse(r.Ultima_consulta_OK);if(!Number.isFinite(elapsed)||elapsed< -300000||elapsed>26*3600000)throw Error('PERSONAL_DESACTUALIZADO_'+branch);}
 }
 return rows;
}
function ids(rows,branch,service){return rows.filter(r=>r.Sucursal_ID===String(branch)&&usable(r)&&(!service||JSON.parse(r.Servicios_ID).map(String).includes(String(service)))).map(r=>String(r.Empleado_ID));}

return {catalog,body,ids};})();
function personalRows(){const r=$('Leer personal vigente').first().json;if(r.error||Number(r.statusCode)!==200)throw Error('ERROR_LECTURA_PERSONAL');return Personal.catalog(Personal.body(r).values,Date.now());}
function personalIds(branch,service){return Personal.ids(personalRows(),branch,service);}

const SPA_WATER = {'24077':['151268','151233'],'24079':['151269','151302'],'24080':['151239'],'24082':['151270'],'24221':['151905']};
function spaResolve(rows, request, branch, people, weekday) {
  const fail=(state,message)=>({ok:false,state,message});
  const n=Number(people), b=String(branch), raw=spaNorm(request);
  if (/\bh[ iy]*dra\s*lips?\b/.test(raw)) return fail('SERVICIO_NO_OFRECIDO','No ofrecemos Hidra Lips. No corresponde consultar horarios ni solicitar pagos.');
  if (/\b(tantrico|tantricos|erotico|eroticos|sexual|sexuales)\b/.test(raw)) return fail('SERVICIO_NO_OFRECIDO','No ofrecemos masajes tántricos, eróticos ni servicios sexuales.');
  if (!Number.isInteger(n)||n<1) return fail('DATOS_INCOMPLETOS','Indica el número de personas.');
  const all=rows.filter(r=>spaId(r)&&spaNorm(r['Nombre del servicio']));
  let family=spaFamily(request,n), direct=[];
  const numeric=/^\d+$/.test(String(request).trim());
  if(numeric) {
    direct=all.filter(r=>spaId(r)===String(request).trim());
    const live=direct.filter(spaActive);
    if(live.length===1) family=spaFamily(live[0]['Nombre del servicio'],n);
  }
  let water=[], massage=[], canonical, type='DIRECTO';
  if (family) {
    canonical=family.canonical;
    if(!family.mod) return fail('DATOS_INCOMPLETOS','Indica la modalidad de la experiencia.');
    if((family.mod==='individual'&&n!==1)||(family.mod==='pareja'&&n!==2)||(family.mod==='tribu'&&n<3)) return fail('NO_COMPATIBLE','La modalidad de la experiencia no coincide con el número de personas.');
    const sauna=family.root==='elephant_glow';
    if(sauna&&(b!=='24079'||n>3)) return fail('NO_COMPATIBLE',b!=='24079'?'Elephant Glow con sauna se agenda únicamente en Polanco.':'El sauna tiene capacidad máxima de 3 personas. No puede reservarse una sesión de sauna para 4 o más personas.');
    if(family.root==='temazcal_bliss'&&b!=='24080') return fail('NO_COMPATIBLE','Temazcal Bliss se agenda únicamente en Juárez.');
    const premium=family.root.startsWith('premium_day_spa');
    type=premium?'DIRECTO':'COMPUESTO';
    const same=r=>spaFamily(r['Nombre del servicio'],n)?.canonical===canonical;
    if(sauna) {
      const ids=SPA_SAUNA_IDS[family.mod];
      water=all.filter(r=>spaId(r)===ids[0]&&same(r)&&spaNorm(r['Nombre del servicio']).startsWith('sauna '));
      massage=all.filter(r=>spaId(r)===ids[1]&&same(r)&&spaNorm(r['Nombre del servicio']).startsWith('masaje '));
    } else {
      if(!premium) water=all.filter(r=>same(r)&&/^(jacuzzi|temazcal)\b/.test(spaNorm(r['Nombre del servicio'])));
      massage=all.filter(r=>same(r)&&(spaNorm(r['Nombre del servicio']).startsWith('masaje ')||family.root==='premium_day_spa_facial'&&!/^(jacuzzi|temazcal)/.test(spaNorm(r['Nombre del servicio']))));
    }
  } else {
    if(!numeric) direct=all.filter(r=>spaNorm(r['Nombre del servicio'])===raw);
    if(!direct.length) return fail('SERVICIO_NO_ENCONTRADO','No hay coincidencia exacta del tratamiento en el catálogo de esta sucursal. Aclara el nombre o la duración; no lo sustituyas por otro.');
    massage=direct;
    canonical=spaCanonical(request,n);
  }
  function unique(list,part) {
    if(!list.length) return fail('SERVICIO_NO_CONFIGURADO','Falta un componente exacto y autorizado de '+part+' en la hoja de esta sucursal. Requiere revisión; no equivale a agenda ocupada.');
    const active=list.filter(spaActive);
    if(!active.length) return fail('SERVICIO_INACTIVO','El componente de '+part+' figura inactivo. No puede agendarse.');
    const byId=new Map();
    for(const r of active) {
      const id=spaId(r), prev=byId.get(id);
      if(prev&&(spaNorm(prev['Nombre del servicio'])!==spaNorm(r['Nombre del servicio']))) return fail('SERVICIO_AMBIGUO','El mismo ID tiene filas activas contradictorias. Revisa la hoja.');
      byId.set(id,r);
    }
    if(byId.size!==1) return fail('SERVICIO_AMBIGUO','Hay más de un ID activo para el tratamiento solicitado. Requiere aclaración.');
    const r=[...byId.values()][0];
    return {ok:true,row:r,id:spaId(r)};
  }
  const m=unique(massage,'masaje o tratamiento'); if(!m.ok)return m;
  if(personalIds(b,m.id).length<n)return fail('PERSONAL_INSUFICIENTE','No hay suficientes terapeutas vigentes habilitadas para este servicio. Requiere revisión.');
  let w=null;if(type==='COMPUESTO'){w=unique(water,'sauna, jacuzzi o temazcal');if(!w.ok)return w;}
  if(!family) {
    const cat=spaNorm(m.row['Categoría']),name=spaNorm(m.row['Nombre del servicio']);
    if(!/^(masajes?|facial(?:es)?|circuito)/.test(cat)||/\b(cabina|prueba|signature)\b/.test(name)) return fail('SERVICIO_NO_AUTOMATIZABLE','El servicio o complemento existe, pero no tiene una ruta de recursos autorizada para agendarlo automáticamente. Requiere asesor.');
    if(/\b(pareja|en pareja)\b/.test(name+' '+cat)&&n!==2) return fail('NO_COMPATIBLE','El servicio de pareja requiere 2 personas.');
    if(/\bindividual\b/.test(name+' '+cat)&&n!==1) return fail('NO_COMPATIBLE','El servicio individual requiere 1 persona.');
    if(/\btribu\b/.test(name+' '+cat)&&n<3) return fail('NO_COMPATIBLE','El servicio de tribu requiere al menos 3 personas.');
    canonical=spaCanonical(m.row['Nombre del servicio'],n);
  }
  const sauna=family?.root==='elephant_glow',thermal=sauna?'SAUNA':family?.root==='temazcal_bliss'?'TEMAZCAL':w?'JACUZZI':null;
  // Apply existing operational rules after resolving identity, including numeric IDs.
  const capacity=sauna?3:w?({'24077':8,'24079':18,'24080':6,'24082':2,'24221':6}[b]||0):personalIds(b,m.id).length;
  if(n>capacity)return fail('NO_COMPATIBLE','La cantidad solicitada supera la capacidad configurada para los recursos de esta experiencia en la sucursal.');
  if(weekday===6&&canonical.includes('_individual')&&b!=='24082')return fail('NO_COMPATIBLE','Los sábados el servicio individual solo está disponible en Lomas.');
  return {ok:true,canonical,family:family?.root||null,modality:family?.mod||null,type,water:w,massage:m,thermal,offset:w?40:0,therapists:personalIds(b,m.id),resources:sauna?['151614']:thermal==='TEMAZCAL'?['151266']:w?(SPA_WATER[b]||[]):[]};
}

// ======================================================
// DATOS BASE DESDE "draft Normalizar contexto"
// ======================================================
const d = $('Normalizar contexto de ejecución1').first().json || {};


// ======================================================
// FUNCIONES AUXILIARES
// ======================================================

function limpiar(valor) {
  return String(valor ?? '').trim();
}

function texto(valor) {
  return limpiar(valor)
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/[_-]+/g, ' ')
    .replace(/\s+/g, ' ')
    .toLowerCase();
}

function slug(valor) {
  return texto(valor)
    .replace(/[^a-z0-9\s]/g, ' ')
    .replace(/\s+/g, '_')
    .replace(/^_+|_+$/g, '');
}

function hora(valor) {
  let h = limpiar(valor).toLowerCase();

  if (!h) return null;

  // Formato AM / PM
  const ampm = h.match(/^(\d{1,2})(?::(\d{2}))?\s*(am|pm)$/);

  if (ampm) {
    let hh = Number(ampm[1]);
    const mm = Number(ampm[2] || 0);

    if (hh < 1 || hh > 12 || mm > 59) {
      return null;
    }

    if (ampm[3] === 'pm' && hh !== 12) {
      hh += 12;
    }

    if (ampm[3] === 'am' && hh === 12) {
      hh = 0;
    }

    return String(hh).padStart(2, '0') + ':' + String(mm).padStart(2, '0');
  }

  // Si llega solamente "15"
  if (/^\d{1,2}$/.test(h)) {
    h += ':00';
  }

  // HH:mm o HH:mm:ss
  const match = h.match(/^(\d{1,2}):(\d{2})(?::\d{2})?$/);

  if (!match) {
    return null;
  }

  const hh = Number(match[1]);
  const mm = Number(match[2]);

  if (hh > 23 || mm > 59) {
    return null;
  }

  return String(hh).padStart(2, '0') + ':' + String(mm).padStart(2, '0');
}

function booleano(valor) {
  if (typeof valor === 'boolean') {
    return valor;
  }

  return ['1', 'true', 'si', 'sí', 'yes'].includes(texto(valor));
}

function sucursalId(valor) {
  const equivalencias = {
    '24077': '24077',
    valle: '24077',
    'del valle': '24077',

    '24079': '24079',
    polanco: '24079',
    polanquito: '24079',

    '24080': '24080',
    juarez: '24080',
    'centro juarez': '24080',

    '24082': '24082',
    lomas: '24082',
    'lomas de chapultepec': '24082',

    '24221': '24221',
    roma: '24221',
    'roma norte': '24221',
    'colonia roma': '24221'
  };

  const limpio = texto(valor)
    .replace(/^inside\s+spa\s+/, '')
    .replace(/^spa\s+/, '')
    .replace(/^sucursal\s+/, '');

  return equivalencias[limpio] || limpiar(valor) || null;
}

function servicioCanonico(v,p){return spaCanonical(v,p);}


// ======================================================
// NORMALIZACIÓN DE DATOS
// ======================================================

const personas = Number(
  d.numero_personas ??
  d.personas ??
  0
);

const servicioOriginal = [
  d.servicio_confirmado, d.servicio, d.servicio_busqueda,
  d.servicio_pabau_id, d.service_id, d.servicio_id,
  d['servicio usuario'], d.nombre_servicio
].map(limpiar).find(Boolean) || '';

const servicio = servicioCanonico(
  servicioOriginal,
  personas
);

const servicioPabauIdSolicitado =
  /^\d+$/.test(servicioOriginal)
    ? servicioOriginal
    : null;

const sucursal = sucursalId(
  d.sucursal
);

const fecha = limpiar(
  d.fecha ??
  d['fecha   '] ??
  d['fecha ']
);

const horario = hora(
  d.horario_normalizado ??
  d.horario ??
  d['horario '] ??
  d.hora
);

const subscriberId = limpiar(
  d.subscriber_id
);

const firstName = limpiar(
  d.first_name ??
  d.nombre ??
  d.nombre_completo
);

const lastName = limpiar(
  d.last_name
);

const email = limpiar(
  d.email ??
  d.correo
).toLowerCase();

const phone = limpiar(
  d.phone ??
  d.telefono
);

const esFeriadoManual = booleano(
  d.es_feriado ??
  d.feriado
);


// ======================================================
// VALIDACIÓN DE CAMPOS OBLIGATORIOS
// ======================================================

const faltantes = [];
if(!String(d.solicitud_id||'').trim())faltantes.push('solicitud_id');
if(d.servicio && d.servicio_confirmado && spaCanonical(d.servicio,Number(d.numero_personas))!==spaCanonical(d.servicio_confirmado,Number(d.numero_personas)))faltantes.push('servicio_no_coincide');

if (!servicio) {
  faltantes.push('servicio');
}

if (!sucursal) {
  faltantes.push('sucursal');
}

if (!fecha) {
  faltantes.push('fecha');
}

if (!horario) {
  faltantes.push('horario');
}

if (!Number.isInteger(personas) || personas < 1) {
  faltantes.push('número de personas');
}


// ======================================================
// SALIDA
// ======================================================

return [
  {
    json: {
      // Conserva TODO lo que viene desde
      // "draft Normalizar contexto"
      ...d,

      subscriber_id: subscriberId,

      first_name: firstName,

      last_name: lastName,

      email,

      phone,

      servicio,

      servicio_busqueda: servicioOriginal,

      servicio_pabau_id_solicitado:
        servicioPabauIdSolicitado,

      nombre_servicio_usuario:
        limpiar(
          d.nombre_servicio ??
          d['servicio usuario']
        ) || servicioOriginal,

      'servicio usuario':
        limpiar(
          d['servicio usuario']
        ) || servicioOriginal,

      sucursal_solicitada:
        limpiar(
          d.sucursal_solicitada ??
          d.sucursal_original ??
          d.sucursal
        ),

      sucursal,

      fecha,

      hora: horario,

      horario,

      horario_normalizado: horario,

      personas,

      numero_personas: personas,

      es_feriado_manual:
        esFeriadoManual,

      faltantes: [
        ...new Set(faltantes)
      ],

      datos_completos:
        faltantes.length === 0
    }
  }
];

// Identidad exacta del servicio. Las filas vigentes se leen de Google Sheets.
function spaNorm(v) {
  return String(v ?? '').normalize('NFD').replace(/[\u0300-\u036f]/g, '')
    .toLowerCase().replace(/buddha|budhas|budas|buda\b/g, 'budha')
    .replace(/fulldayspa/g, 'full day spa').replace(/3\s*p(?:x|ax)\b/g, 'tribu')
    .replace(/[^a-z0-9]+/g, ' ').replace(/\s+/g, ' ').trim();
}
function spaFamily(v, n) {
  let t = spaNorm(v).replace(/^(masaje|jacuzzi) /, '');
  t = t.replace(/^sauna elephant glow/, 'elephant glow').replace(/^premium budha/, 'budha');
  const m = t.match(/^(premium(?: day(?: spa)?)?(?: facial)?|full(?: day(?: spa)?)?|budha(?: 70)?|temazcal bliss|elephant glow)(?: (individual|pareja|tribu))?$/);
  if (!m) return null;
  const root = m[1].startsWith('premium') ? (m[1].includes('facial') ? 'premium_day_spa_facial' : 'premium_day_spa')
    : m[1].startsWith('full') ? 'full_day_spa' : m[1].startsWith('budha') ? 'budha_70' : m[1].replace(/ /g, '_');
  const mod = m[2] || (n === 1 ? 'individual' : n === 2 ? 'pareja' : n >= 3 ? 'tribu' : '');
  return {root, mod, canonical: root + (mod ? '_' + mod : '')};
}
function spaCanonical(v, n) {
  const f = spaFamily(v, n);
  return f ? f.canonical : spaNorm(v).replace(/ /g, '_') || null;
}
function spaId(r) { const v=r.ID ?? r[' '] ?? r.id; return /^\d+(?:\.0+)?$/.test(String(v??'').trim()) ? String(Number(v)) : ''; }
function spaYes(v) { return ['si','true','1','yes'].includes(spaNorm(v)); }
function spaActive(r) { return spaYes(r.Activo) && !spaNorm(r['Categoría']).includes('disabled'); }
const SPA_SAUNA_IDS = {individual:['3570984','3570987'],pareja:['3570985','3570988'],tribu:['3570986','3570989']};
const Personal=(()=>{const HEADERS=['Clave','Sucursal_ID','Sucursal','Empleado_ID','Nombre','Cargo','Estado_API','Presente_API','Servicios_ID','Modo','Ultima_consulta_OK','Ultima_vez_visto','Tipo','Observaciones'];
