const SPA_WATER = {'24077':['151268','151233'],'24079':['151269','151302'],'24080':['151239'],'24082':['151270'],'24221':['151905']};
function spaResolve(rows, request, branch, people, weekday) {
  const fail=(state,message)=>({ok:false,state,message});
  const n=Number(people), b=String(branch), raw=spaNorm(request);
  if (/\bh[ iy]*dra\s*lips?\b/.test(raw)) return fail('SERVICIO_NO_OFRECIDO','No ofrecemos Hidra Lips. No corresponde consultar horarios ni solicitar pagos.');
  if (/\b(tantrico|tantricos|erotico|eroticos|sexual|sexuales)\b/.test(raw)) return fail('SERVICIO_NO_OFRECIDO','No ofrecemos masajes tántricos, eróticos ni servicios sexuales.');
  if (!Number.isInteger(n)||n<1) return fail('DATOS_INCOMPLETOS','Indica el número de personas.');
  const all=rows.filter(r=>spaId(r)&&spaNorm(r['Nombre del servicio']));
  let family=spaFamily(request,n), direct=[];
  const numeric=/^\d+$/.test(String(request).trim());
  if(numeric) {
    direct=all.filter(r=>spaId(r)===String(request).trim());
    const live=direct.filter(spaActive);
    if(live.length===1) family=spaFamily(live[0]['Nombre del servicio'],n);
  }
  let water=[], massage=[], canonical, type='DIRECTO';
  if (family) {
    canonical=family.canonical;
    if(!family.mod) return fail('DATOS_INCOMPLETOS','Indica la modalidad de la experiencia.');
    if((family.mod==='individual'&&n!==1)||(family.mod==='pareja'&&n!==2)||(family.mod==='tribu'&&n<3)) return fail('NO_COMPATIBLE','La modalidad de la experiencia no coincide con el número de personas.');
    const sauna=family.root==='elephant_glow';
    if(sauna&&(b!=='24079'||n>3)) return fail('NO_COMPATIBLE',b!=='24079'?'Elephant Glow con sauna se agenda únicamente en Polanco.':'El sauna tiene capacidad máxima de 3 personas. No puede reservarse una sesión de sauna para 4 o más personas.');
    if(family.root==='temazcal_bliss'&&b!=='24080') return fail('NO_COMPATIBLE','Temazcal Bliss se agenda únicamente en Juárez.');
    const premium=family.root.startsWith('premium_day_spa');
    type=premium?'DIRECTO':'COMPUESTO';
    const same=r=>spaFamily(r['Nombre del servicio'],n)?.canonical===canonical;
    if(sauna) {
      const ids=SPA_SAUNA_IDS[family.mod];
      water=all.filter(r=>spaId(r)===ids[0]&&same(r)&&spaNorm(r['Nombre del servicio']).startsWith('sauna '));
      massage=all.filter(r=>spaId(r)===ids[1]&&same(r)&&spaNorm(r['Nombre del servicio']).startsWith('masaje '));
    } else {
      if(!premium) water=all.filter(r=>same(r)&&/^(jacuzzi|temazcal)\b/.test(spaNorm(r['Nombre del servicio'])));
      massage=all.filter(r=>same(r)&&(spaNorm(r['Nombre del servicio']).startsWith('masaje ')||family.root==='premium_day_spa_facial'&&!/^(jacuzzi|temazcal)/.test(spaNorm(r['Nombre del servicio']))));
    }
  } else {
    if(!numeric) direct=all.filter(r=>spaNorm(r['Nombre del servicio'])===raw);
    if(!direct.length) return fail('SERVICIO_NO_ENCONTRADO','No hay coincidencia exacta del tratamiento en el catálogo de esta sucursal. Aclara el nombre o la duración; no lo sustituyas por otro.');
    massage=direct;
    canonical=spaCanonical(request,n);
  }
  function unique(list,part) {
    if(!list.length) return fail('SERVICIO_NO_CONFIGURADO','Falta un componente exacto y autorizado de '+part+' en la hoja de esta sucursal. Requiere revisión; no equivale a agenda ocupada.');
    const active=list.filter(spaActive);
    if(!active.length) return fail('SERVICIO_INACTIVO','El componente de '+part+' figura inactivo. No puede agendarse.');
    const byId=new Map();
    for(const r of active) {
      const id=spaId(r), prev=byId.get(id);
      if(prev&&(spaNorm(prev['Nombre del servicio'])!==spaNorm(r['Nombre del servicio']))) return fail('SERVICIO_AMBIGUO','El mismo ID tiene filas activas contradictorias. Revisa la hoja.');
      byId.set(id,r);
    }
    if(byId.size!==1) return fail('SERVICIO_AMBIGUO','Hay más de un ID activo para el tratamiento solicitado. Requiere aclaración.');
    const r=[...byId.values()][0];
    return {ok:true,row:r,id:spaId(r)};
  }
  const m=unique(massage,'masaje o tratamiento'); if(!m.ok)return m;
  if(personalIds(b,m.id).length<n)return fail('PERSONAL_INSUFICIENTE','No hay suficientes terapeutas vigentes habilitadas para este servicio. Requiere revisión.');
  let w=null;if(type==='COMPUESTO'){w=unique(water,'sauna, jacuzzi o temazcal');if(!w.ok)return w;}
