  }
  const sauna=family?.root==='elephant_glow',thermal=sauna?'SAUNA':family?.root==='temazcal_bliss'?'TEMAZCAL':w?'JACUZZI':null;
  // Apply existing operational rules after resolving identity, including numeric IDs.
  const capacity=sauna?3:w?({'24077':8,'24079':18,'24080':6,'24082':2,'24221':6}[b]||0):personalIds(b,m.id).length;
  if(n>capacity)return fail('NO_COMPATIBLE','La cantidad solicitada supera la capacidad configurada para los recursos de esta experiencia en la sucursal.');
  if(weekday===6&&canonical.includes('_individual')&&b!=='24082')return fail('NO_COMPATIBLE','Los sábados el servicio individual solo está disponible en Lomas.');
