}

const d = $input.first().json;
const errores = [];

function minutos(hora) {
  const [h, m] = String(hora || '').split(':').map(Number);
  return h * 60 + m;
}

function fechaValida(valor) {
  if (!/^\d{4}-\d{2}-\d{2}$/.test(String(valor || ''))) return false;
  const [y, m, day] = valor.split('-').map(Number);
  const prueba = new Date(Date.UTC(y, m - 1, day));
  return prueba.getUTCFullYear() === y && prueba.getUTCMonth() === m - 1 && prueba.getUTCDate() === day;
}

function isoFecha(y, m, day) {
  return String(y).padStart(4, '0') + '-' + String(m).padStart(2, '0') + '-' + String(day).padStart(2, '0');
}

function lunesNumero(anio, mes, numero) {
  const primero = new Date(Date.UTC(anio, mes - 1, 1));
  const desplazamiento = (8 - primero.getUTCDay()) % 7;
  return isoFecha(anio, mes, 1 + desplazamiento + (numero - 1) * 7);
}

function esFeriadoMexico(fecha) {
  const [anio] = fecha.split('-').map(Number);
  const fijos = new Set([
    isoFecha(anio, 1, 1),
    lunesNumero(anio, 2, 1),
    lunesNumero(anio, 3, 3),
    isoFecha(anio, 5, 1),
    isoFecha(anio, 9, 16),
    lunesNumero(anio, 11, 3),
    isoFecha(anio, 12, 25)
  ]);
  if (anio % 6 === 2) fijos.add(isoFecha(anio, 10, 1));
  return fijos.has(fecha);
}

function crearSlots(inicio, fin) {
  const resultado = [];
  for (let actual = minutos(inicio), ultimo = minutos(fin); actual <= ultimo; actual += 40) {
    const h = Math.floor(actual / 60);
    const m = actual % 60;
    resultado.push(String(h).padStart(2, '0') + ':' + String(m).padStart(2, '0'));
  }
  return resultado;
}

const sucursales = new Set(['24077', '24079', '24080', '24082', '24221']);
const capacidades = { '24077': 8, '24079': 18, '24080': 6, '24082': 2, '24221': 6 };
const personas = Number(d.numero_personas ?? d.personas ?? 0);

if (!String(d.servicio_busqueda || d.servicio || "").trim()) errores.push("Servicio no recibido");
if (!sucursales.has(String(d.sucursal))) errores.push('Sucursal no válida');
if (!Number.isInteger(personas) || personas < 1) errores.push('Número de personas inválido');
const familiaOperativa=spaFamily(d.servicio,personas);
const esSauna=familiaOperativa?.root==='elephant_glow';
const usaAgua=['full_day_spa','budha_70','temazcal_bliss'].includes(familiaOperativa?.root)||d.servicio==='promo_amigas';
const limite=esSauna?3:usaAgua?capacidades[d.sucursal]:personalIds(d.sucursal).length;
if (esSauna && String(d.sucursal)!=='24079') errores.push('Elephant Glow con sauna solo está configurado en Polanco');
if (/h[ iy]*dra\s*lips?/.test(spaNorm(d.servicio_busqueda||d.servicio))) errores.push('Hidra Lips no se ofrece');
if (sucursales.has(String(d.sucursal)) && personas > limite) {
  errores.push('La cantidad solicitada supera la capacidad de esta sucursal');
}
if (String(d.servicio || '').startsWith('temazcal_bliss') && d.sucursal !== '24080') {
  errores.push('Temazcal Bliss solo está disponible en Juárez');
}
if (d.servicio === 'promo_amigas' && personas < 4) errores.push('Promo Amigas requiere mínimo 4 personas');
if (String(d.servicio || '').includes('_individual') && personas !== 1) errores.push('El servicio individual requiere 1 terapeuta');
if (String(d.servicio || '').includes('_pareja') && personas !== 2) errores.push('El servicio de pareja requiere 2 terapeutas');
if (String(d.servicio || '').includes('_tribu') && personas < 3) errores.push('El servicio tribu requiere mínimo 3 terapeutas');
if (!fechaValida(d.fecha)) errores.push('Fecha inválida');

let diaSemana = null;
if (fechaValida(d.fecha)) {
  const [y, m, day] = d.fecha.split('-').map(Number);
  diaSemana = new Date(Date.UTC(y, m - 1, day)).getUTCDay();
}
const esFeriado = Boolean(d.es_feriado_manual) || (fechaValida(d.fecha) && esFeriadoMexico(d.fecha));
const esFinSemana = diaSemana === 0 || diaSemana === 6;
const tipoHorario = esFinSemana || esFeriado ? 'fin_semana_feriado' : 'lunes_viernes';
const CONFIG_HORARIOS = {
  '24077': { nombre: 'Valle', cierre: '19:00', primer_semana: '11:00', primer_fin_feriado: '10:20', ultimo_slot: '17:40' },
  '24082': { nombre: 'Lomas', cierre: '19:00', primer_semana: '11:00', primer_fin_feriado: '10:20', ultimo_slot: '17:40' },
  '24079': { nombre: 'Polanco', cierre: '20:00', primer_semana: '11:00', primer_fin_feriado: '10:20', ultimo_slot: '18:20' },
  '24080': { nombre: 'Juárez', cierre: '20:00', primer_semana: '11:00', primer_fin_feriado: '10:20', ultimo_slot: '18:20' },
  // Roma conserva los mismos horarios operativos de Juárez.
  '24221': { nombre: 'Roma', cierre: '20:00', primer_semana: '11:00', primer_fin_feriado: '10:20', ultimo_slot: '18:20' }
};
const horarioSucursal = CONFIG_HORARIOS[String(d.sucursal)] || null;
const primerSlot = tipoHorario === 'fin_semana_feriado'
  ? horarioSucursal?.primer_fin_feriado
  : horarioSucursal?.primer_semana;
const ultimoSlot = horarioSucursal?.ultimo_slot;
const slotsPermitidos = primerSlot && ultimoSlot ? crearSlots(primerSlot, ultimoSlot) : [];

// El horario del cliente es una referencia, no una validación bloqueante.
// Si no coincide con un slot oficial, el flujo continúa y busca alternativas reales.
const horarioSolicitadoEsSlot = Boolean(d.horario_normalizado) &&
  slotsPermitidos.includes(d.horario_normalizado);
if (diaSemana === 6 && String(d.servicio || '').includes('_individual') && d.sucursal !== '24082') {
  errores.push('Los sábados el servicio individual solo está disponible en Lomas');
}

return [{
  json: {
    ...d,
    personas,
    numero_personas: personas,
    dia_semana: diaSemana,
    es_feriado: esFeriado,
    tipo_horario: tipoHorario,
    nombre_sucursal_config: horarioSucursal?.nombre || null,
    cierre_sucursal: horarioSucursal?.cierre || null,
    primer_slot_jacuzzi: primerSlot || null,
    ultimo_slot_jacuzzi: ultimoSlot || null,
    slots_permitidos: slotsPermitidos,
    horario_solicitado_es_slot: horarioSolicitadoEsSlot,
    horario_usado_como_referencia: Boolean(d.horario_normalizado) && !horarioSolicitadoEsSlot,
    errores_baratos: [...new Set(errores)],
    paso_validaciones_baratas: errores.length === 0
  }
}];

