// Selección de presentación: recibe únicamente opciones ya verificadas.
// No crea horas, no cambia recursos y no añade límites de disponibilidad.
function seleccionarHorariosVariados(opciones) {
  const porHora = new Map();
  for (const opcion of opciones || []) {
    if (!opcion || opcion.disponible === false) continue;
    const m = String(opcion.hora_inicio || '').trim().match(/^(\d{1,2}):(\d{2})$/);
    if (!m || Number(m[1]) > 23 || Number(m[2]) > 59) continue;
    const minuto = Number(m[1]) * 60 + Number(m[2]);
    // En otra sucursal, conservar el orden previo para desempatar la misma hora.
    if (!porHora.has(minuto)) porHora.set(minuto, { minuto, opcion });
  }
  const candidatas = [...porHora.values()].sort((a,b) => a.minuto-b.minuto);
  if (candidatas.length <= 3) return candidatas.map(x => x.opcion);
  // Son referencias flexibles; todos los candidatos conservan elegibilidad.
  const referencias = [11*60, 14*60+20, 17*60];
  let mejor = null;
  for (let i=0; i<candidatas.length-2; i++) {
    for (let j=i+1; j<candidatas.length-1; j++) {
      for (let k=j+1; k<candidatas.length; k++) {
        const trio = [candidatas[i],candidatas[j],candidatas[k]];
        const distancia = trio.reduce((total,x,n) => total+Math.abs(x.minuto-referencias[n]),0);
        const separacion = Math.min(trio[1].minuto-trio[0].minuto,trio[2].minuto-trio[1].minuto);
        const amplitud = trio[2].minuto-trio[0].minuto;
        if (!mejor || distancia<mejor.distancia ||
          (distancia===mejor.distancia && (separacion>mejor.separacion ||
          (separacion===mejor.separacion && amplitud>mejor.amplitud)))) {
          mejor = { trio, distancia, separacion, amplitud };
        }
      }
    }
  }
  return mejor.trio.map(x => x.opcion);
}

