// Identidad exacta del servicio. Las filas vigentes se leen de Google Sheets.
function spaNorm(v) {
  return String(v ?? '').normalize('NFD').replace(/[\u0300-\u036f]/g, '')
    .toLowerCase().replace(/buddha|budhas|budas|buda\b/g, 'budha')
    .replace(/fulldayspa/g, 'full day spa').replace(/3\s*p(?:x|ax)\b/g, 'tribu')
    .replace(/[^a-z0-9]+/g, ' ').replace(/\s+/g, ' ').trim();
}
function spaFamily(v, n) {
  let t = spaNorm(v).replace(/^(masaje|jacuzzi) /, '');
  t = t.replace(/^sauna elephant glow/, 'elephant glow').replace(/^premium budha/, 'budha');
  const m = t.match(/^(premium(?: day(?: spa)?)?(?: facial)?|full(?: day(?: spa)?)?|budha(?: 70)?|temazcal bliss|elephant glow)(?: (individual|pareja|tribu))?$/);
  if (!m) return null;
  const root = m[1].startsWith('premium') ? (m[1].includes('facial') ? 'premium_day_spa_facial' : 'premium_day_spa')
    : m[1].startsWith('full') ? 'full_day_spa' : m[1].startsWith('budha') ? 'budha_70' : m[1].replace(/ /g, '_');
  const mod = m[2] || (n === 1 ? 'individual' : n === 2 ? 'pareja' : n >= 3 ? 'tribu' : '');
  return {root, mod, canonical: root + (mod ? '_' + mod : '')};
}
function spaCanonical(v, n) {
  const f = spaFamily(v, n);
  return f ? f.canonical : spaNorm(v).replace(/ /g, '_') || null;
}
function spaId(r) { const v=r.ID ?? r[' '] ?? r.id; return /^\d+(?:\.0+)?$/.test(String(v??'').trim()) ? String(Number(v)) : ''; }
function spaYes(v) { return ['si','true','1','yes'].includes(spaNorm(v)); }
function spaActive(r) { return spaYes(r.Activo) && !spaNorm(r['Categoría']).includes('disabled'); }
