parameters.query:
SELECT COALESCE(jsonb_agg(to_jsonb(d)), '[]'::jsonb) AS borradores
FROM public.reservas_draft d WHERE d.subscriber_id::text=$1::text
AND (CASE WHEN $2::text<>'' THEN d.id::text=$2::text ELSE d.solicitud_id=$3::text END);

parameters.jsCode:
const n=$('Normalizar entrada').first().json;
const request=$('Normalizar contexto de ejecución1').first().json;
const rows=$input.first().json.borradores||[];
if(rows.length>1)throw new Error('SOLICITUD_CON_VARIOS_BORRADORES');
if(request.reserva_draft_id && !rows.length)throw new Error('BORRADOR_NO_PERTENECE_AL_CONTACTO');
const d=rows[0]||null;
if(d){
 const start=String(d.jacuzzi_inicio||d.masaje_inicio||'');
 if(String(d.subscriber_id)!==String(request.subscriber_id)||String(d.servicio)!==String(n.servicio)||String(d.sucursal)!==String(n.sucursal)||start.slice(0,10)!==String(n.fecha).slice(0,10)||start.slice(11,16)!==String(n.horario).slice(0,5)||Number(d.numero_personas||d.personas)!==Number(n.numero_personas||n.personas))throw new Error('NO_SOBRESCRIBIR_PRERESERVA: la solicitud difiere del borrador guardado.');
}
return [{json:{...n,borrador_existente:d,ya_guardado:!!d}}];

const n=$input.first().json;const d=n.borrador_existente;
const closed=['expirado_sin_pago','cancelando_expirada','cancelado'].includes(String(d.estado_reserva));
const start=String(d.jacuzzi_inicio||d.masaje_inicio||'');
return [{json:{ok:!closed,estado:closed?'PRERESERVA_CERRADA':'BORRADOR_EXISTENTE',estado_reserva:d.estado_reserva,reserva_draft_id:String(d.id),solicitud_id:$('Normalizar contexto de ejecución1').first().json.solicitud_id,subscriber_id:String(d.subscriber_id),servicio:d.servicio,servicio_confirmado:d.servicio,sucursal:String(d.sucursal),fecha:start.slice(0,10),horario:start.slice(11,16),numero_personas:Number(d.numero_personas||d.personas),pago_recibido:d.pago_recibido===true,reserva_confirmada:d.reserva_confirmada===true,pago_pendiente:!closed&&d.pago_recibido!==true,retencion_iniciada:d.pabau_reservado===true,mensaje:closed?'Esta pre-reserva ya está cerrada. Solicita una nueva consulta sin reutilizar este borrador.':'Esta solicitud ya tiene su propio borrador. No se creó otra cita ni se reinició la retención.'}}];

const d=$input.first().json||{};const p=$('Preparar borrador universal').first().json;
if(!d.id)throw new Error('SOLICITUD_Y_BORRADOR_NO_COINCIDEN: No se sobrescribió el borrador existente.');
if(String(d.subscriber_id)!==String(p.subscriber_id)||d.solicitud_id!==p.solicitud_id||d.servicio!==p.servicio)throw new Error('IDENTIDAD_DE_BORRADOR_INVALIDA');
return [{json:d}];

const Personal=(()=>{const HEADERS=['Clave','Sucursal_ID','Sucursal','Empleado_ID','Nombre','Cargo','Estado_API','Presente_API','Servicios_ID','Modo','Ultima_consulta_OK','Ultima_vez_visto','Tipo','Observaciones'];
const BRANCHES={'24077':'Valle','24079':'Polanco','24080':'Juárez','24082':'Lomas','24221':'Roma'};
function norm(v){return String(v??'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').trim().toLowerCase();}
function validId(v){return /^[1-9]\d*$/.test(String(v??''));}
function body(r){let b=r?.body??r?.data??r;if(typeof b==='string'){try{b=JSON.parse(b);}catch{throw Error('RESPUESTA_NO_JSON');}}return b;}
function records(values){
 if(!Array.isArray(values)||!values.length)return [];
 if(HEADERS.some((h,i)=>values[0][i]!==h))throw Error('ENCABEZADOS_PERSONAL_NO_COINCIDEN');
 const out=values.slice(1).filter(r=>r.some(v=>String(v??'').trim())).map(r=>Object.fromEntries(HEADERS.map((h,i)=>[h,r[i]??''])));
 const seen=new Set();for(const r of out){if(!BRANCHES[String(r.Sucursal_ID)]||!validId(r.Empleado_ID)||r.Clave!==r.Sucursal_ID+':'+r.Empleado_ID||seen.has(r.Clave))throw Error('CLAVE_PERSONAL_INVALIDA_O_DUPLICADA');seen.add(r.Clave);if(!['AUTO','SI','NO'].includes(String(r.Modo).toUpperCase()))throw Error('MODO_PERSONAL_INVALIDO');}
 return out;
}
function kind(u){const name=norm(u.full_name);if(/\b(jacuzzi|sauna|temazcal|cabina|camilla|room)\b/.test(name))return 'RECURSO';if(/^inside\b/.test(name))return 'CUENTA_INTERNA';if(norm(u.job_title)==='employee'&&Number(u.admin)===0)return 'CANDIDATA_TERAPEUTA';return 'REVISAR_ROL';}
function usable(r){
 const mode=String(r.Modo).toUpperCase(),status=norm(r.Estado_API);
 return String(r.Presente_API)==='SI'&&['','pending','active','enabled'].includes(status)&&!['RECURSO','CUENTA_INTERNA'].includes(r.Tipo)&&mode!=='NO'&&(mode==='SI'||(mode==='AUTO'&&r.Tipo==='CANDIDATA_TERAPEUTA'));
}
function sync(responses,oldValues,stamp){
 const old=records(oldValues),fresh=new Map(),seenBranches=new Set();
 for(const entry of responses){
  const branch=String(entry.sucursal_id);if(!BRANCHES[branch]||seenBranches.has(branch))throw Error('SUCURSAL_INVALIDA_O_DUPLICADA');seenBranches.add(branch);
  const r=entry.respuesta;
  if(entry.codigo_http!==200||entry.consulta_http_exitosa!==true||entry.fallo_consulta||r?.success!==true||!Array.isArray(r.users)||!Number.isInteger(r.total)||r.total<=0||r.total!==r.users.length)throw Error('CONSULTA_PERSONAL_INCOMPLETA_'+branch);
  if(r.has_more===true||r.next_page||r.next||r.pagination?.has_more===true||Number(r.pagination?.total_pages||1)>1)throw Error('PERSONAL_PAGINADO_NO_COMPLETO_'+branch);
  for(const u of r.users){
   if(!validId(u.id)||!String(u.full_name??'').trim()||typeof u.job_title!=='string'||![0,1].includes(Number(u.admin))||!Array.isArray(u.assigned_locations)||!u.assigned_locations.every(validId)||!Array.isArray(u.assigned_services)||!u.assigned_services.every(validId))throw Error('USUARIO_PERSONAL_INVALIDO_'+branch);
   if(!u.assigned_locations.map(String).includes(branch))throw Error('USUARIO_DE_OTRA_SUCURSAL_'+branch);
   const key=branch+':'+u.id;if(fresh.has(key))throw Error('USUARIO_DUPLICADO_'+key);
   const prev=old.find(x=>x.Clave===key);
   fresh.set(key,{Clave:key,Sucursal_ID:branch,Sucursal:BRANCHES[branch],Empleado_ID:String(u.id),Nombre:u.full_name.trim(),Cargo:u.job_title,Estado_API:String(u.status??''),Presente_API:'SI',Servicios_ID:JSON.stringify([...new Set(u.assigned_services.map(String))]),Modo:prev?.Modo||'AUTO',Ultima_consulta_OK:stamp,Ultima_vez_visto:stamp,Tipo:kind(u),Observaciones:prev?.Observaciones||''});
  }
 }
 if(seenBranches.size!==5)throw Error('FALTAN_SUCURSALES');
 // Una ausencia solo se aplica después de validar las cinco consultas completas.
 for(const prev of old)if(!fresh.has(prev.Clave))fresh.set(prev.Clave,{...prev,Presente_API:'NO',Ultima_consulta_OK:stamp});
 const rows=[...fresh.values()].sort((a,b)=>a.Sucursal_ID.localeCompare(b.Sucursal_ID)||a.Nombre.localeCompare(b.Nombre));
 if(rows.length>=999)throw Error('CAPACIDAD_HOJA_PERSONAL_EXCEDIDA');
 return [HEADERS,...rows.map(r=>HEADERS.map(h=>String(r[h]??'')))];
}
function catalog(values,now){
 const rows=records(values);if(!rows.length)throw Error('PERSONAL_NO_SINCRONIZADO');
 for(const branch of Object.keys(BRANCHES)){
  const rr=rows.filter(r=>r.Sucursal_ID===branch);if(!rr.length)throw Error('PERSONAL_SUCURSAL_SIN_DATOS_'+branch);
  for(const r of rr){const elapsed=now-Date.parse(r.Ultima_consulta_OK);if(!Number.isFinite(elapsed)||elapsed< -300000||elapsed>26*3600000)throw Error('PERSONAL_DESACTUALIZADO_'+branch);}
 }
 return rows;
}
function ids(rows,branch,service){return rows.filter(r=>r.Sucursal_ID===String(branch)&&usable(r)&&(!service||JSON.parse(r.Servicios_ID).map(String).includes(String(service)))).map(r=>String(r.Empleado_ID));}

return {catalog,body,ids};})();
function personalRows(){const r=$('Leer personal vigente').first().json;if(r.error||Number(r.statusCode)!==200)throw Error('ERROR_LECTURA_PERSONAL');return Personal.catalog(Personal.body(r).values,Date.now());}
function personalIds(branch,service){return Personal.ids(personalRows(),branch,service);}

personalRows();return $('Conservar entrada para personal').all();
